import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String[] lines = new String(System.in.readAllBytes()).split("\r?\n", -1);
        String s = Long.parseLong(lines[0].trim()) != 0 ? lines[1] : "";
        // Each change of the effective bit (starting from 0) needs one suffix flip.
        char current = '0';
        long answer = 0;
        for (int i = 0; i < s.length(); i++)
            if (s.charAt(i) != current) {
                answer++;
                current = s.charAt(i);
            }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	lines := strings.Split(string(raw), "\n")
	s := ""
	if strings.TrimSpace(lines[0]) != "0" {
		s = strings.TrimSuffix(lines[1], "\r")
	}
	// Each change of the effective bit (starting from 0) needs one suffix flip.
	current := byte('0')
	answer := 0
	for i := 0; i < len(s); i++ {
		if s[i] != current {
			answer++
			current = s[i]
		}
	}
	fmt.Println(answer)
}
